import { add, divide, multiply, subtract } from './calc.ts';

export class ParseError extends Error {
  readonly input: string;

  constructor(message: string, input: string) {
    super(message);
    this.name = 'ParseError';
    this.input = input;
  }
}

type Token =
  | { type: 'number'; value: number }
  | { type: 'operator'; value: '+' | '-' | '*' | '/' }
  | { type: 'lparen' }
  | { type: 'rparen' };

const NUMBER_PATTERN = /^\d+(\.\d+)?/;

function tokenize(input: string): Token[] {
  const tokens: Token[] = [];
  let pos = 0;

  while (pos < input.length) {
    const ch = input[pos];

    if (ch !== undefined && /\s/.test(ch)) {
      pos += 1;
      continue;
    }

    if (ch === '+' || ch === '-' || ch === '*' || ch === '/') {
      tokens.push({ type: 'operator', value: ch });
      pos += 1;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: 'lparen' });
      pos += 1;
      continue;
    }

    if (ch === ')') {
      tokens.push({ type: 'rparen' });
      pos += 1;
      continue;
    }

    const match = NUMBER_PATTERN.exec(input.slice(pos));
    if (match !== null) {
      tokens.push({ type: 'number', value: Number(match[0]) });
      pos += match[0].length;
      continue;
    }

    throw new ParseError(`Unexpected character '${ch}' at position ${pos}`, input);
  }

  return tokens;
}

function parseFactor(tokens: Token[], pos: number, input: string): [number, number] {
  const token = tokens[pos];

  if (token === undefined) {
    throw new ParseError('Unexpected end of input, expected a number or \'(\'', input);
  }

  if (token.type === 'number') {
    return [token.value, pos + 1];
  }

  if (token.type === 'lparen') {
    const [value, nextPos] = parseExpression(tokens, pos + 1, input);
    const closing = tokens[nextPos];
    if (closing === undefined || closing.type !== 'rparen') {
      throw new ParseError('Missing closing \')\'', input);
    }
    return [value, nextPos + 1];
  }

  throw new ParseError('Expected a number or \'(\'', input);
}

function parseTerm(tokens: Token[], pos: number, input: string): [number, number] {
  let [left, currentPos] = parseFactor(tokens, pos, input);

  while (true) {
    const token = tokens[currentPos];
    if (token === undefined || token.type !== 'operator' || (token.value !== '*' && token.value !== '/')) {
      break;
    }

    const [right, nextPos] = parseFactor(tokens, currentPos + 1, input);
    left = token.value === '*' ? multiply(left, right) : divide(left, right);
    currentPos = nextPos;
  }

  return [left, currentPos];
}

function parseExpression(tokens: Token[], pos: number, input: string): [number, number] {
  let [left, currentPos] = parseTerm(tokens, pos, input);

  while (true) {
    const token = tokens[currentPos];
    if (token === undefined || token.type !== 'operator' || (token.value !== '+' && token.value !== '-')) {
      break;
    }

    const [right, nextPos] = parseTerm(tokens, currentPos + 1, input);
    left = token.value === '+' ? add(left, right) : subtract(left, right);
    currentPos = nextPos;
  }

  return [left, currentPos];
}

export function evaluate(input: string): number {
  const tokens = tokenize(input);

  if (tokens.length === 0) {
    throw new ParseError('Empty input', input);
  }

  const [value, pos] = parseExpression(tokens, 0, input);

  if (pos !== tokens.length) {
    throw new ParseError('Unexpected trailing input', input);
  }

  return value;
}

